   有翻译时气泡位置与普通消息一致
   ========================================================= */

/* 带翻译的气泡整体向上校正 */
.msg-plain-them:has(.msg-translation-wrapper),
.msg-plain-me:has(.msg-translation-wrapper) {
  transform:
    translateY(-4px) !important;

  margin-bottom:
    -4px !important;
}

/* 防止翻译本身再制造顶部空隙 */
.msg-translation-wrapper {
  margin-top:
    0 !important;

  padding-top:
    0 !important;
}

/* 翻译内部第一层也不准留顶部 margin */
.msg-translation-wrapper > :first-child,
.msg-translation-content,
.msg-translation-content > :first-child {
  margin-top:
    0 !important;

  padding-top:
    0 !important;
}

/* =========================================================
   DATE
   ========================================================= */

.date-divider-custom {
  position:
    relative !important;

  display:
    inline-flex !important;

  align-items:
    center !important;

  justify-content:
    center !important;

  padding:
    3px 8px !important;

  background:
    rgba(255,255,255,.48) !important;

  color:
