/* =========================================================
   SMALL SCREEN
   ========================================================= */

@media (max-width: 390px) {

  .chat-detail-screen .header-avatar-container {
    width:
      38px !important;

    height:
      38px !important;

    flex-basis:
      38px !important;
  }

  .chat-detail-screen .header-avatar-container::before {
    inset:
      -4px !important;
  }

  .chat-detail-screen .header-avatar-container::after {
    right:
      -2px !important;

    bottom:
      -2px !important;

    padding:
      1.5px 3.7px 1.9px !important;

    font-size:
      4.5px !important;
  }

  .chat-detail-screen .chat-header-title::after {
    top:
      calc(100% + 4px) !important;

    font-size:
      4.85px !important;

    letter-spacing:
      .88px !important;
  }

  .chat-detail-screen .header-btn-phone::after,
  .chat-detail-screen .header-btn-video::after,
  .chat-detail-screen .header-btn-info::after {
    font-size:
      10px !important;
  }

  .chat-detail-screen .header-btn-video::before,
  .chat-detail-screen .header-btn-info::before {
    margin:
      0 6px !important;
  }

  .chat-messages-area {
    padding-top:
      12px !important;
  }

  .chat-messages-area::before {
    font-size:
      6.9px !important;

    padding:
      3px 0 7px !important;
  }

  .msg-avatar-them-inner::before,
  .msg-avatar-me-inner::before {
    padding:
      1.7px 3.3px 2px !important;

    font-size:
      4px !important;
  }

  .msg-avatar-them-inner::after,
  .msg-avatar-me-inner::after {
    padding:
      .5px 3.8px .9px !important;

    font-size:
      4.05px !important;
  }

  .msg-bubble-wrapper.is-first,
  .msg-bubble-wrapper.is-mid {
    margin-bottom:
      9px !important;
  }

  .msg-them + .msg-them,
  .msg-me + .msg-me {
    margin-top:
      5px !important;
  }

  .msg-plain-them:has(.voice-msg),
  .msg-plain-me:has(.voice-msg),
  .msg-plain-them:has(.voice-msg-me),
  .msg-plain-me:has(.voice-msg-me),
  .msg-plain-them:has(.voice-msg-them),
  .msg-plain-me:has(.voice-msg-them) {
    min-width:
      208px !important;

    max-width:
      79% !important;
  }

  .voice-waveform {
    min-width:
      66px !important;

    max-width:
      122px !important;
  }

  .voice-replay-btn,
  .voice-replay-button,
  .voice-replay,
  .voice-restart-btn,
  .voice-restart-button,
  .voice-download-btn,
  .voice-download-button {
    flex-basis:
      17px !important;

    width:
      17px !important;

    min-width:
      17px !important;
  }

  .msg-transfer-card {
    width:
      174px !important;

    min-width:
      174px !important;

    max-width:
      59vw !important;

    min-height:
      100px !important;
  }

  .msg-redpacket-card {
    width:
      170px !important;

    min-width:
      170px !important;

    max-width:
      58vw !important;

    min-height:
      98px !important;
  }

  .input-area-custom {
    padding-bottom:
      14px !important;
  }

  .input-row-wrapper {
    transform:
      translateY(-11px) !important;
  }

  .input-btn-plus {
    flex-basis:
      38px !important;

    width:
      38px !important;

    height:
      38px !important;

    min-width:
      38px !important;

    min-height:
      38px !important;
  }

  .input-btn-plus::after {
    width:
      35px !important;

    height:
      35px !important;
  }

  .input-action-bar-custom {
    height:
      38px !important;

    min-height:
      38px !important;
  }

  :root {
    --sg-hidden-action-size:
      23px;
  }

  .input-btn-mic,
  .input-btn-sticker,
  .input-btn-ai {
    height:
      30px !important;

    min-height:
      30px !important;
  }

  .input-action-bar-custom::before {
    left:
      78px !important;

    font-size:
      12px !important;

    letter-spacing:
      .25px !important;
  }

  .input-box-custom {
    height:
      34px !important;

    font-size:
      13px !important;
  }
