/* =========================================================
   KLEIN_BLUE THEME
   char = 白色雾面玻璃
   user = 克莱因蓝纯色雾面气泡
   ========================================================= */

:root {
  --sg-blue-050: rgba(252,250,254,.96);
  --sg-blue-100: rgba(249,246,252,.95);
  --sg-blue-150: rgba(241,243,249,.93);
  --sg-blue-200: rgba(231,234,244,.92);
  --sg-blue-300: rgba(207,212,231,.90);
  --sg-blue-ink: #45527f;
  --sg-blue-muted: #929cbe;

  --sg-glass:
    rgba(255,255,255,.70);

  --sg-border:
    rgba(255,255,255,.84);

  --sg-text:
    #343038;

  --sg-muted:
    #8d98bb;

  --sg-faint:
    #ced2dd;

  --sg-shadow:
    0 5px 16px rgba(71,85,131,.026),
    0 1px 2px rgba(51,61,94,.014);

  --sg-card-shadow:
    0 8px 22px rgba(71,85,131,.032),
    0 1px 3px rgba(51,61,94,.016);

  --sg-input-glass:
    rgba(251,248,253,.82);

  --sg-input-border:
    rgba(231,234,244,.90);

  --sg-input-shadow:
    0 7px 19px rgba(74,89,138,.030),
    inset 0 1px 0 rgba(255,255,255,.70);

  --sg-input-text:
    #455381;

  --sg-input-placeholder:
    #a5adc9;

  --sg-send-bg:
    rgba(243,245,250,.90);

  --sg-send-border:
    rgba(225,228,239,.94);

  --sg-send-color:
    #7481ab;
}

