/* 小贴纸标签：超小、实心白底、细黑边，贴头像右上 */
.msg-avatar-them-inner::before,
.msg-avatar-me-inner::before {
  position:
    absolute !important;

  left:
    auto !important;

  bottom:
    auto !important;

  right:
    -1px !important;

  top:
    -4px !important;

  min-width:
    18px !important;

  width:
    auto !important;

